from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "empty": [],
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
    }
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 5), (2, 7), (5, 8)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 5], days) == expected


def test_parse_transcript_log_skips_lines_and_normalizes_fields():
    lines = ["", "\t \n", "# comment", "  # indented", " a , 2 , 1 ", "b,3,0", "c,4, "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": 3, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,2", "a,2,1,extra", "a,2.5,1"])
def test_parse_transcript_log_errors_count_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["  ", " # comment", "ok,1,1", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    old = {"id": "b", "day": 9, "flagged": True}
    last = {"id": "b", "day": 2, "flagged": False}
    same_day = {"id": "a", "day": 2, "flagged": True}
    earlier_day = {"id": "z", "day": 1, "flagged": None}
    assert dedupe_transcripts([old, same_day, last, earlier_day]) == [
        earlier_day, same_day, last
    ]


def test_daily_flag_counts_includes_gaps_and_boundaries():
    events = parse_transcript_log(
        ["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,3,1", "g,4,1"]
    )
    assert daily_flag_counts(events, 1, 3) == [2, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]


def test_monitor_summary_uses_calendar_days_and_pooled_rate():
    groups = {
        "small": parse_transcript_log(["a,1,1"]),
        "large": parse_transcript_log(["b,2,1", "c,5,0", "d,5,", "e,5,0", "f,5,1", "g,5,0"]),
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.429, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_breaks_ties_by_name_and_excludes_empty_groups():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "a": [{"flagged": True}],
        "low": [{"flagged": None}],
    }
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "low"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorts_keys_and_distinguishes_empty_from_zero():
    groups = {"z": [], "b": [{"flagged": True}], "a": [{"flagged": None}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", 1.0), ("z", None)]


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -2], 0), ([1, 2, 0, 1, -1, 1], 2)])
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
